import {lessonTitles,steps,scenes,phrases,formQuestions,transformations,moods,existenceQuestions,futureQuestions,musicTopics,normalizeAnswer,wordCount,parseStep,formatTime} from './lesson-data.js';

import {loadSavedProgress, persistProgress} from './progress-store.js';

const $=id=>document.getElementById(id);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={step:parseStep(location.hash),view:'student',scene:0,bookChapter:1,drafts:{},labels:{},fieldSteps:{},complete:new Set(),checked:{},times:steps.map(s=>s.minutes*60)};
let timerHandle=null,timerDeadline=0;

const savedProgress=loadSavedProgress(steps.length,scenes.length);
if(savedProgress.status==='restored'){
  const saved=savedProgress.data;
  Object.assign(state,saved,{complete:new Set(saved.complete),view:'student'});
  // An explicit link to a lesson step takes priority over the saved position.
  if(/^#step-[1-8]$/.test(location.hash))state.step=parseStep(location.hash);
}
let unsavedChanges=false;
function showSaveStatus(message,kind='neutral'){
  document.querySelectorAll('[data-save-status]').forEach(el=>{el.textContent=message;el.dataset.kind=kind;});
}
function markUnsaved(){
  if(unsavedChanges)return;
  unsavedChanges=true;
  showSaveStatus('Changes not saved yet. Save progress before you leave.','unsaved');
}
function saveAllProgress(){
  const result=persistProgress(state,steps.length,scenes.length);
  if(result.ok){
    unsavedChanges=false;
    const message='All lesson progress saved on this browser · '+new Date(result.savedAt).toLocaleString();
    showSaveStatus(message,'saved');announce(message);
  }else{
    const message='Could not save on this browser. Your answers are still here. Use Print notes to keep a copy, and check that website storage is allowed.';
    showSaveStatus(message,'error');announce(message);
  }
}

function remember(key,label){state.labels[key]=label;state.fieldSteps[key]=state.step;}
function field(key,label,placeholder='',hint='',rows=3){remember(key,label);return `<div class="field"><label for="${key}">${label}</label><textarea id="${key}" data-key="${key}" rows="${rows}" placeholder="${escape(placeholder)}" ${hint?`aria-describedby="${key}-hint"`:''}>${escape(state.drafts[key]||'')}</textarea>${hint?`<span class="hint" id="${key}-hint">${hint}</span>`:''}</div>`;}
function input(key,label,placeholder=''){remember(key,label);return `<div class="field"><label for="${key}">${label}</label><input id="${key}" type="text" data-key="${key}" value="${escape(state.drafts[key]||'')}" placeholder="${escape(placeholder)}"></div>`;}
function select(key,label,options){remember(key,label);return `<div class="field"><label for="${key}">${label}</label><select id="${key}" data-key="${key}"><option value="">Choose…</option>${options.map(o=>`<option value="${escape(o)}" ${state.drafts[key]===o?'selected':''}>${escape(o)}</option>`).join('')}</select></div>`;}
function choices(key,label,options){remember(key,label);return `<div class="choice-row" role="group" aria-label="${escape(label)}">${options.map(o=>`<button class="choice" data-choice="${key}" data-value="${escape(o)}" aria-pressed="${state.drafts[key]===o}">${escape(o)}</button>`).join('')}</div>`;}
function radio(key,label,options){remember(key,label);return `<div class="quiz-options" role="radiogroup" aria-label="${escape(label)}">${options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="${key}" data-key="${key}" value="${i}" ${String(state.drafts[key])===String(i)?'checked':''}><span>${escape(o)}</span></label>`).join('')}</div>`;}
function checklist(items,prefix){return `<ul class="checklist">${items.map((t,i)=>{const k=prefix+'-'+i;remember(k,t);return `<li><label><input type="checkbox" data-key="${k}" ${state.drafts[k]?'checked':''}><span>${t}</span></label></li>`;}).join('')}</ul>`;}
const credit='<p class="source-credit">Page references follow Sinan Seden’s illustrated storybook. Reading recaps and activities here are lesson material. Storybook adaptation credits Denise Taylor’s <em>The Silent Forest</em>, Open University Press, 2010.</p>';

function opening(){return `<section class="story-hero" aria-label="Lesson opening"><div class="hero-copy"><span class="card-label">THE BIG QUESTION</span><h2>Can music bring us together?</h2><p>A flute. A forest. A connection worth listening for.</p></div><img src="assets/glade.jpg" alt="Eva playing a flute among woodland animals in Sinan’s storybook" width="1680" height="944"></section>
  <section class="card"><span class="card-label">01 / BEGIN WITH YOUR OWN IDEA</span><h2>Listen first. Then take a position.</h2><ol class="steps-list"><li>Listen to the room in silence for ten seconds. Name one sound and the feeling it creates.</li><li>Choose your first response to the question below. There is no single correct opinion.</li><li>Tell a partner why. Ask what might change their mind.</li></ol><p class="prompt">Can people understand one another through music without sharing a language?</p>${choices('opening-position','Your starting position',['Often','Sometimes','Rarely'])}${field('opening-reason','What makes you think so?','I think… because…','Use a personal experience or an example you can explain.')}</section>
  <section class="card"><span class="card-label">02 / OPEN YOUR STORYBOOK</span><h2>Meet Eva and her unusual flute.</h2><p>Your illustrated book is embedded in <strong>Read &amp; Investigate</strong>. Start with its opening pages. Keep <strong>Sound words OFF</strong> during the first reading.</p>${field('opening-prediction','Predict: what connection might the flute create?','I predict that…', 'You will revisit this prediction after the ending.',2)}<div class="note green"><strong>Our language goal:</strong> describe past events with <em>there was / were</em> + adjective–noun; describe actions with verb–adverb combinations. Later, use these patterns to predict music’s future.</div></section>`;}

function reading(){const s=scenes[state.scene],k='read-'+state.scene;return `<div class="note"><strong>Your storybook is here.</strong> Read in the embedded book, then pause for the questions below. Keep most responses oral so the story remains the centre of the lesson.</div>
 <div class="scene-nav" role="tablist" aria-label="Story stages">${scenes.map((s,i)=>`<button id="scene-tab-${i}" class="scene-tab" role="tab" aria-controls="scene-panel" aria-selected="${state.scene===i}" tabindex="${state.scene===i?'0':'-1'}" data-scene="${i}">${i+1}. ${s.title}<small>${s.pages}</small></button>`).join('')}</div>
 <section class="card book-card" aria-label="Embedded illustrated storybook"><div class="book-toolbar"><div><span class="card-label">READ · KEEP SOUND WORDS OFF FIRST</span><h2>${s.title}</h2></div><a id="book-large-link" class="button ghost" href="storybook.html?chapter=${state.bookChapter}" target="_blank" rel="noopener noreferrer">Open larger ↗</a></div><div class="book-checkpoints" role="group" aria-label="Jump to a story page">${[[1,'1 · Opening'],[4,'4 · Tom arrives'],[6,'6 · Not yet'],[8,'8 · River'],[10,'10 · Cause & discussion'],[11,'11 · Repair'],[13,'13 · Clear water'],[14,'14 · Flute'],[15,'15 · Ending']].map(([n,t])=>`<button data-book="${n}" aria-pressed="${state.bookChapter===n}">${t}</button>`).join('')}</div><iframe id="embedded-storybook" class="embedded-storybook" title="Read The Silent Forest illustrated storybook" src="storybook.html?chapter=${state.bookChapter}" allow="fullscreen" allowfullscreen></iframe><p class="hint">The reader loads the book and illustrations directly from your GitHub repository. Internet access is required. Use the book’s Contents, page arrows, Sound words, and text-size controls.</p></section>
 ${state.scene===1?persuasion():''}
 <section class="card" id="scene-panel" role="tabpanel" aria-labelledby="scene-tab-${state.scene}"><span class="card-label">PAUSE AFTER ${s.pages.toUpperCase()}</span><h2 class="scene-title">${s.range}</h2><details class="details"><summary>Review the stage in two sentences</summary><div>${s.recap}</div></details><div class="note green"><strong>Pause and talk:</strong> ${s.pause}</div><div data-activity="reading"><h3>${s.question}</h3>${radio(k,s.question,s.choices)}<button class="button primary" data-check="reading">Check understanding</button><div class="feedback" id="reading-feedback" role="status"></div></div>${state.scene===1?field('story-key-evidence','Choose one key piece of evidence from the whole investigation','On page… we learn that…','One strong example is enough. You do not need notes for every stage.',2):'<p class="hint">Discuss this stage orally. No additional written evidence note is required.</p>'}<div class="checkpoint-actions">${state.scene>0?'<button class="button ghost" data-scene="'+(state.scene-1)+'">← Earlier stage</button>':''}${state.scene<2?'<button class="button ghost" data-scene="'+(state.scene+1)+'">Next reading stage →</button>':'<span class="hint">You have reached the ending. Compare it with your prediction.</span>'}</div></section>
 ${state.scene===2?`<section class="card"><span class="card-label">END OF LESSON 1 · RETELL & REFLECT</span><h2>Two roles. One return.</h2><div class="two-col"><div><span class="card-label">PRACTICAL ACTION</span><p>What did the towns change so the animals could live there again?</p></div><div><span class="card-label">MUSICAL CONNECTION</span><p>What does Eva’s flute do once the forest can support the animals?</p></div></div>${field('reading-distinction','Explain the difference briefly','Repairing the river… The flute…','Then retell the problem, investigation, action, and return orally to a partner.',2)}</section>`:''}${credit}`;}

function persuasion(){return `<section class="card" aria-labelledby="persuasion-title"><span class="card-label">STOP ON STORY PAGE 10 · BEFORE THE RESOLUTION · 8 MINUTES</span><h2 id="persuasion-title">How could Tom win people over?</h2><p>Tom has discovered the cause of the pollution. Pause here before reading page 11.</p><button class="button ghost" data-book="10" aria-pressed="${state.bookChapter===10}">Return to page 10 · The Cause</button><p class="prompt">What could Tom do to persuade more inhabitants of the neighbouring town to help clean up the river?</p><ol class="steps-list"><li><strong>Think · 1 minute:</strong> what might stop people from helping?</li><li><strong>Pair · 2 minutes:</strong> develop one strong action and a reason.</li><li><strong>Role-play · 3 minutes:</strong> one person is Tom; the other is a hesitant inhabitant. Raise one concern and respond. Then swap roles.</li><li><strong>Share · 2 minutes:</strong> present the strongest idea.</li></ol><div class="argument-frame">Tom could ___ because ___.<br>This might persuade people who worry about ___.<br>I understand your concern. We could ___.</div>${field('tom-best-idea','Record only your strongest idea and reason','Tom could… because…','The objection and response can remain oral.',2)}<details class="details"><summary>After speaking: read pages 11–12 and compare</summary><div><button class="button ghost" data-book="11" aria-pressed="${state.bookChapter===11}">Continue to page 11 · The repair</button><p>Was your proposal similar to the towns’ response? Tell your partner one idea you would keep or change.</p></div></details></section>`;}

function noticing(){return `<section class="card"><span class="card-label">SECOND READING · SOUND WORDS ON</span><h2>Ask what the describing word is doing.</h2><p>Revisit the book’s highlighted words and teaching captions. Use the questions below to separate the two patterns.</p><div class="two-col"><div class="grammar-card"><h3>Adjective + noun</h3><p class="rule">The adjective tells us more about a person, place, thing, or idea.</p><p class="big-example"><strong>beautiful</strong> music</p><span class="tag">What kind of music?</span><p class="hint">beautiful = adjective<br>music = noun</p></div><div class="grammar-card adverb"><h3>Verb + adverb</h3><p class="rule">These adverbs tell us how an action happens.</p><p class="big-example">plays <strong>softly</strong></p><span class="tag">How does Eva play?</span><p class="hint">plays = verb<br>softly = adverb</p></div></div><div class="note">The book’s pop-up captions are teaching additions. They make the action easier to describe; they are not quotations from the original story.</div></section>

 <section class="card"><span class="card-label">BUILD A COMPLETE PAST DESCRIPTION</span><h2>There was + adjective + noun</h2><p>Use <strong>there was</strong> to introduce something that existed or happened in the past. It does not mean “in that place” here.</p><div class="grammar-card"><p class="big-example"><strong>There was</strong> <span class="an">a joyful celebration</span> in town.</p><p class="rule">There was + <strong>a/an</strong> + adjective + <strong>singular countable noun</strong></p></div><div class="table-wrap"><table><thead><tr><th scope="col">Noun type</th><th scope="col">Sentence</th><th scope="col">Remember</th></tr></thead><tbody><tr><td>One countable thing</td><td>There was <span class="an">an unusual sound</span>.</td><td>a/an depends on the next sound.</td></tr><tr><td>Uncountable</td><td>There was <span class="an">beautiful music</span>.</td><td>No a/an before music.</td></tr><tr><td>Plural</td><td>There were <span class="an">loud voices</span>.</td><td>Use were with plural nouns.</td></tr></tbody></table></div><p class="hint">These are teaching sentences inspired by the story. The adjective describes the noun after it, not was or were.</p><div class="note green"><strong>Two ways to describe the event:</strong><br>The villagers <span class="va">celebrated joyfully</span>.<br>There was <span class="an">a joyful celebration</span> in town.</div></section>
 <section class="card" data-activity="sort"><span class="card-label">YOUR TURN · SIX PHRASES</span><h2>Sort by the word being described.</h2>${phrases.map((p,i)=>{const k='sort-'+i;remember(k,'Pattern: '+p.text);return `<div class="phrase-item"><label class="phrase-text" for="${k}">${p.text}<small>${p.source}</small></label><select id="${k}" data-key="${k}"><option value="">Choose a pattern…</option><option value="an" ${state.drafts[k]==='an'?'selected':''}>Adjective + noun</option><option value="va" ${state.drafts[k]==='va'?'selected':''}>Verb + adverb</option></select></div>`;}).join('')}<div class="checkpoint-actions"><button class="button primary" data-check="sort">Check my patterns</button></div><div class="feedback" id="sort-feedback" role="status"></div></section>
 <section class="card"><h2>The pattern is a relationship, too.</h2><p>The adverb does not always sit immediately after its verb:</p><p class="big-example">Eva played <strong>the flute</strong> <span class="va">softly</span>.</p><p>With an object, we usually put a manner adverb after the object, or before the verb: <em>Eva softly played the flute.</em></p><details class="details"><summary>Ready for a small extension?</summary><div><p><strong>A beautifully sunny day</strong> (page 13): beautifully describes <em>sunny</em>, not an action.</p><p><strong>The music sounds beautiful.</strong> Here, sounds links music to its description. Use the adjective beautiful.</p><p>Many manner adverbs end in -ly, but not all: <em>plays well</em>, <em>moves fast</em>. Ask what the word does, rather than checking only its ending.</p></div></details></section>`;}

function practice(){return `<section class="card" data-activity="forms"><span class="card-label">01 / CHOOSE THE RIGHT FORM</span><h2>What does the missing word describe?</h2><p>Complete the four quick checks, then explain one answer to a partner.</p>${formQuestions.map((q,i)=>`<div class="checkpoint"><h3>${i+1}. ${q.before} ____ ${q.after}</h3>${radio('form-'+i,'Complete: '+q.before+'…'+q.after,q.options)}</div>`).join('')}<button class="button primary" data-check="forms">Check word choices</button><div class="feedback" id="forms-feedback" role="status"></div></section>
 <section class="card" data-activity="existence"><span class="card-label">02 / WAS, WERE, A OR AN?</span><h2>Look at the noun.</h2>${existenceQuestions.map((q,i)=>`<div class="checkpoint"><h3>${i+1}. ${q.prompt}</h3>${radio('existence-'+i,q.prompt,q.options)}</div>`).join('')}<button class="button primary" data-check="existence">Check sentence frames</button><div class="feedback" id="existence-feedback" role="status"></div></section>
 <section class="card"><span class="card-label">03 / SAME EVENT · ANOTHER CONSTRUCTION</span><h2>From an action to “there was”.</h2><div class="table-wrap"><table><thead><tr><th scope="col">Verb + adverb</th><th scope="col">There was + adjective + noun</th></tr></thead><tbody><tr><td>Tom <span class="va">investigated carefully</span>.</td><td>There was <span class="an">a careful investigation</span> of the river.</td></tr></tbody></table></div><p class="hint">investigated → investigation · carefully → careful</p></section>
 <section class="card" data-activity="transform"><h2>Complete three quick rewrites.</h2>${transformations.map((t,i)=>{let k='transform-'+i;remember(k,'Rewrite: '+t.original);return `<div class="transform-item"><p><strong>${i+1}.</strong> ${t.original}</p><label for="${k}" class="hint">Complete the adjective–noun phrase.</label><div class="transform-input"><span>${t.before}</span><input id="${k}" type="text" data-key="${k}" value="${escape(state.drafts[k]||'')}" placeholder="adjective" autocomplete="off" spellcheck="false" aria-label="Adjective for rewrite ${i+1}"><span>${t.after}</span></div></div>`;}).join('')}<button class="button primary" data-check="transform">Check rewrites</button><div class="feedback" id="transform-feedback" role="status"></div></section>
 <section class="card"><span class="card-label">04 / STORY SCENE REPORTER · ORAL CHALLENGE</span><h2>Describe it. Can your partner identify it?</h2><ol class="steps-list"><li>Secretly choose The Silence, The Investigation, or The Return.</li><li>Study that story scene for 20 seconds, then hide it by scrolling back here.</li><li>Describe it using <strong>there was / were + adjective–noun</strong> and a <strong>past verb + adverb</strong>.</li><li>Your partner listens, asks for one extra detail, and identifies the scene. Then swap roles.</li></ol><div class="argument-frame">There was a/an ___. / There were ___.<br>Eva, Tom, or the inhabitants ___-ed ___.</div>${field('scene-reporter-note','Optional: record your strongest two sentences','There was…\nEva/Tom/the inhabitants…','Speaking is the main task. Write only if it helps you remember your best version.',2)}</section>`;}

function soundtrack(){return `<section class="card"><span class="card-label">REVISIT · THE SAME GLADE / THREE SOUNDTRACKS</span><h2>Keep your eyes here. Change what you hear.</h2><img class="scene-visual" src="assets/glade.jpg" alt="The same glade illustration shown for all three audio sketches" width="1680" height="944"><ol class="steps-list"><li>Listen to each eight-second audio sketch. Keep looking at this same picture.</li><li>Describe its mood using an adjective–noun phrase.</li><li>Imagine how a narrator or character would act. Use a verb–adverb combination.</li></ol><div class="moods">${moods.map(m=>`<article class="mood"><span class="mood-symbol" aria-hidden="true">${m.symbol}</span><h3>${m.name}</h3><p>${m.description}</p><audio controls preload="none" aria-label="${m.name} audio sketch"><source src="assets/${m.id}.wav" type="audio/wav">Audio is unavailable in this browser.</audio><button class="mood-select" data-choice="selected-mood" data-value="${m.name}" aria-pressed="${state.drafts['selected-mood']===m.name}">Choose ${m.name.toLowerCase()}</button></article>`).join('')}</div><p class="mini-caption">Original tone sketches for this activity. The labels suggest an intended mood; different responses are welcome. These are separate from the storybook’s illustrations.</p><div id="selected-mood-note" class="selected-mood-note" role="status">${state.drafts['selected-mood']?'Your choice: '+escape(state.drafts['selected-mood']):''}</div></section>
 <section class="card"><span class="card-label">END OF LESSON 2 · APPLY & COMPARE</span><h2>What did you hear?</h2><div class="two-col">${field('mood-description','Describe what you heard','There was a gentle melody. / There were slow notes.','Use there was / were + adjective–noun.',2)}${field('mood-action','Describe the action','The musician played softly.','Use a past verb + adverb.',2)}</div>${field('mood-reason','Why does that soundtrack fit your interpretation?','It suggests… because…','Mention something you actually hear: pace, pitch, pauses, or contrasting notes.',2)}<div class="note green"><strong>Compare with a partner:</strong> did the same sound create the same feeling? What might explain a different response?</div>${field('mood-difference','Record a different interpretation','My partner heard… whereas I…','Share your two grammar patterns, then save your progress. Next lesson: how might a new way of hearing music change this experience?',2)}</section>`;}

function createScene(){return `<section class="card"><span class="card-label">THE BRIDGE / STORY → FUTURE EXPERIENCE</span><h2>What if Eva’s audience changed?</h2><p>The flute connects Eva with an audience. Now imagine a future town celebration: people could listen in the same place, through a stream, or in a virtual space.</p><ol class="steps-list"><li>Recall the sound or celebration in the story using <strong>there was</strong>.</li><li>Imagine a future listening experience. What could change for the performer or audience?</li><li>Change the time reference before you make your prediction.</li></ol>${field('bridge-experience','What could change about the experience?','In the story, there was… In a future celebration…','This is an imagined possibility, not a claim about current technology use.',2)}</section>
 <section class="card"><span class="card-label">01 / KEEP THE PATTERN · CHANGE THE TIME</span><h2>Past description → future prediction</h2><div class="table-wrap"><table><thead><tr><th scope="col">Time</th><th scope="col">Verb + adverb</th><th scope="col">Adjective + noun</th></tr></thead><tbody><tr><td>Past story event</td><td>The villagers celebrated joyfully.</td><td><strong>There was</strong> a joyful celebration.</td></tr><tr><td>Imagined future event</td><td>The audience <strong>may celebrate</strong> joyfully.</td><td><strong>There may be</strong> a joyful celebration.</td></tr><tr><td>Predicted future change</td><td>Attendance <strong>will rise</strong> steadily.</td><td><strong>There will be</strong> a steady rise in attendance.</td></tr></tbody></table></div><div class="note"><strong>Use there was for the past.</strong> For the future, use <strong>there will be</strong>, or <strong>there may / might be</strong> when you want to show uncertainty. After will/may/might, use be—even before a plural noun.</div><p class="hint">All future examples here are hypothetical. They are language models, not forecasts or statistics.</p></section>
 <section class="card"><span class="card-label">02 / MEET THE EIGHT TOPICS</span><h2>What might change?</h2><p>Read each term before the discussion. A “trend” is a general direction of change. Name what changes: sales, use, attendance, or popularity.</p><div class="topic-grid">${musicTopics.map(t=>`<article class="topic-card"><span aria-hidden="true" class="topic-symbol">${t.icon}</span><h3>${t.name}</h3><p>${t.meaning}</p><span class="hint"><strong>Possible measure:</strong> ${t.measure}</span></article>`).join('')}</div><p class="hint">“Hologram popstars” is the coursebook’s term for performances using digital or projected images; staging methods vary.</p></section>
 <section class="card"><span class="card-label">03 / SAY HOW THE CHANGE MIGHT HAPPEN</span><h2>Use a small word bank.</h2><div class="table-wrap"><table><thead><tr><th scope="col">Verb + adverb</th><th scope="col">Adjective + noun</th></tr></thead><tbody><tr><td>increase gradually</td><td>a gradual increase</td></tr><tr><td>rise steadily</td><td>a steady rise</td></tr><tr><td>fall slightly</td><td>a slight fall</td></tr><tr><td>change significantly</td><td>a significant change</td></tr></tbody></table></div><div class="note green"><strong>Be precise:</strong> “CDs may fall” is unclear. Try “Sales of CDs may fall slightly because…”</div></section>
 <section class="card" data-activity="future"><h2>Check the bridge before you discuss.</h2>${futureQuestions.map((q,i)=>`<div class="checkpoint"><h3>${i+1}. ${q.prompt}</h3>${radio('future-'+i,q.prompt,q.options)}</div>`).join('')}<button class="button primary" data-check="future">Check prediction patterns</button><div class="feedback" id="future-feedback" role="status"></div>${field('bridge-pair','Make one prediction in both ways','___ may increase gradually because…\nThere may be a gradual increase in… because…','Keep the topic, time frame, and meaning the same.',3)}</section>`;}

function discussion(){return `<section class="card"><span class="card-label">UNIT 1 / PRINTED PAGE 9 / EXERCISE 6</span><h2>Scan eight topics. Investigate two.</h2><p>First form a quick opinion about every topic. Then select two topics and develop predictions that name what changes, for whom, and why.</p><div class="note green"><strong>Your time frame:</strong> over the next five years. Predictions need reasons, not invented statistics.</div><ol class="steps-list"><li>Scan and classify all eight topics.</li><li>As a pair, choose two focus topics and develop one detailed prediction for each.</li><li>Exchange ideas with another pair and ask a follow-up question.</li><li>Add one original trend or technology for Lesson 4.</li></ol></section>
 <section class="card"><span class="card-label">01 / QUICK SCAN · 5 MINUTES</span><h2>Consider every topic briefly.</h2><div class="topic-grid">${musicTopics.map((t,i)=>`<article class="topic-card"><h3>${t.name}</h3><p class="hint">Think about ${t.measure}.</p>${select('trend-direction-'+i,'Your prediction for '+t.name,['Rise / increase','Fall / decrease','Stay steady','Mixed / uncertain'])}</article>`).join('')}</div><p class="hint">These are opinions, not right-or-wrong answers. Keep this stage quick.</p></section>
 <section class="card"><span class="card-label">02 / TWO FOCUS TOPICS · 12 MINUTES</span><h2>Give each prediction a reason.</h2><div class="argument-frame">Over the next five years, ___ may increase gradually because ___.<br>There may be a gradual increase in ___ because ___.<br>However, ___ might ___ if ___.</div>${[1,2].map(i=>`<div class="track"><div class="track-label">PAIR FOCUS · PREDICTION ${i}</div>${select('forecast-topic-'+i,'Focus topic '+i,musicTopics.map(t=>t.name))}${field('forecast-'+i,'Prediction and reason '+i,i===1?'Use a future verb + adverb…':'Use there will / may / might be + adjective–noun…','Name the measure and explain the reason.',3)}</div>`).join('')}<div class="note"><strong>Vocabulary challenge:</strong> naturally reuse at least two words such as <em>melody, pitch, tempo, soundtrack, track</em>, or another word from your Unit 1 vocabulary.</div></section>
 <section class="card"><span class="card-label">03 / EXCHANGE · 8 MINUTES</span><h2>Borrow an idea—politely.</h2><p>Join another pair. Present your two predictions, ask one follow-up question, and record the most useful alternative you hear.</p>${field('forecast-exchange','A useful idea from another pair','They predicted… because… We agreed/disagreed because…','You may use or challenge this idea in Lesson 4.',3)}</section>
 <section class="card"><span class="card-label">04 / SOMETHING NEW · 5 MINUTES</span><h2>What else could change music?</h2>${input('forecast-new-idea','Another trend or technology','Your own idea')}${field('forecast-new-impact','How might it change making, sharing, or hearing music?','There might be… / People may… because…','Carry your strongest coursebook ideas and this new possibility into the writing workshop.',3)}</section>`;}

function finish(){return `<section class="card"><span class="card-label">01 / RETRIEVE · 5 MINUTES</span><h2>Past, future, or future possibility?</h2><p>Read these sentences aloud. Identify the time reference and the target pattern.</p><div class="grammar-card"><p><strong>There was</strong> a joyful celebration beside the clean river.</p><p>Streaming services <strong>may develop rapidly</strong>.</p><p><strong>There might be</strong> a significant change in virtual concerts.</p></div></section>
 <section class="card"><span class="card-label">02 / STUDY A MODEL · 7 MINUTES</span><h2>How does this forecast work?</h2><p class="model-paragraph">In <em>The Silent Forest</em>, there was a joyful celebration after the river became clean. Over the next five years, there may be a significant increase in virtual concerts because they can connect audiences in different places. Streaming services may also develop rapidly and offer more personalised tracks. However, live concerts will probably remain popular because people value sharing music in the same space. Wireless earbuds might improve gradually, especially their sound quality. New technology may change how we hear music, but human connection will remain important.</p>${checklist(['I found the past story reference.','I found a future adjective–noun construction.','I found a future verb–adverb construction.','I found reasons supporting the predictions.'],'model-check')}</section>
 <section class="card"><span class="card-label">03 / PLAN · 6 MINUTES</span><h2>Choose before you write.</h2><div class="two-col">${select('writing-topic-1','Page 9 topic 1',musicTopics.map(t=>t.name))}${select('writing-topic-2','Page 9 topic 2',musicTopics.map(t=>t.name))}</div>${input('writing-own-idea','One additional trend or technology','Your own idea')}${field('writing-plan','Reasons and useful vocabulary','Topic 1 → reason…\nTopic 2 → reason…\nUseful words…','Include at least two Unit 1 music words.',4)}</section>
 <section class="card"><span class="card-label">04 / INDIVIDUAL DRAFT · 12 MINUTES</span><h2>How might music change over the next five years?</h2><p>Write <strong>80–100 words</strong> about your two page 9 topics and one additional idea. Give reasons for your predictions.</p><div class="sentence-bank" aria-label="Optional sentence starters"><span>In the story, there was…</span><span>Over the next five years…</span><span>There may be…</span><span>…may increase gradually because…</span></div>${field('exit-response','Your music forecast','Look back briefly, then look ahead…','Use may or might when you want to show uncertainty.',8)}<p class="word-count" id="exit-count" aria-live="polite">${wordCount(state.drafts['exit-response']||'')} words · suggested 80–100</p></section>
 <section class="card"><span class="card-label">05 / PEER REVIEW · 6 MINUTES</span><h2>Help the forecast become clearer.</h2>${checklist(['The forecast is 80–100 words.','It refers briefly to the story using there was.','It predicts changes in two page 9 topics.','It includes one additional idea.','It uses a future adjective–noun pattern and a future verb–adverb pattern.','The main predictions have understandable reasons.'],'exit-check')}<p class="hint">Respond to meaning first. Mark one strong sentence and suggest one useful improvement.</p></section>
 <section class="card"><span class="card-label">06 / REVISE & SUBMIT · 4 MINUTES</span><h2>Make at least two useful changes.</h2>${input('exit-past','Past: there was + adjective–noun','Copy your past story description.')}${input('exit-future-noun','Future: there will / may / might be + adjective–noun','Copy your future noun construction.')}${input('exit-future-verb','Future: verb + adverb','Copy your future action or change prediction.')}${field('exit-revision','What did you improve after peer feedback?','I changed… because…','Name at least one meaningful revision.',2)}<button class="button primary" data-check="exit">Review my final checklist</button><div class="feedback" id="exit-feedback" role="status"></div><button class="button ghost" data-action="print">Print my notes</button><p class="hint">Your teacher or partner checks meaning and grammar in context. The automatic review checks completion and length only.</p></section><div id="finish-message"></div>${credit}`;}

const renderers=[opening,reading,noticing,practice,soundtrack,createScene,discussion,finish];

function renderTeacher(){const t=steps[state.step].teacher;$('teacher-panel').innerHTML=`<div class="teacher-heading"><span aria-hidden="true">✦</span> TEACHER GUIDE</div><h3>Book checkpoint</h3><p>${t.pages}</p><h3>Learning intention</h3><p>${t.goal}</p><h3>Lead the activity</h3><ul>${t.actions.map(a=>`<li>${a}</li>`).join('')}</ul><h3>Ask aloud</h3><p><em>${t.say}</em></p><details><summary>What to listen for</summary><p>${t.look}</p></details><details><summary>Support & stretch</summary><p><strong>Support:</strong> ${t.support}</p><p><strong>Stretch:</strong> ${t.extend}</p></details><div class="teacher-ready"><strong>BEFORE YOU MOVE ON</strong>${t.ready}</div>${state.step===0?'<details><summary>Prepare the four lessons</summary><p>Use the embedded storybook in Step 2. Have Unit 1 page 9 available. Internet is needed for the embedded book. Use speakers for Step 5 if possible.</p><p>Lesson 1 · Story &amp; persuasion: steps 1–2 (40 min). Lesson 2 · Grammar &amp; sound: steps 3–5 (40 min). Lesson 3 · The future of music: steps 6–7 (40 min). Lesson 4 · Forecast workshop: step 8 (40 min).</p><p>Student view hides these planning notes when projecting. It uses the same lesson steps.</p></details>':''}`;}
function renderNavigation(){$('step-nav').innerHTML=steps.map((s,i)=>`${i===0||s.lesson!==steps[i-1].lesson?`<div class="nav-lesson">Lesson ${s.lesson} · 40 min<br>${lessonTitles[s.lesson-1]}</div>`:''}<button class="nav-step ${state.complete.has(i)?'done':''}" data-step="${i}" ${i===state.step?'aria-current="step"':''}><span class="step-number">${state.complete.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${s.short}</span></button>`).join('');$('progress').value=state.complete.size;$('progress-label').textContent=`${state.complete.size} of 8 steps complete`;$('complete-step').setAttribute('aria-pressed',String(state.complete.has(state.step)));$('complete-step').textContent=state.complete.has(state.step)?'✓ Step complete':'○ Mark complete';}
function render(){const s=steps[state.step];$('lesson').classList.toggle('reading-step',state.step===1);$('step-kicker').textContent=`LESSON ${s.lesson} / STEP ${state.step+1} OF 8`;$('step-meta').textContent=s.group;$('step-title').textContent=s.title;$('step-intro').textContent=s.intro;$('step-content').innerHTML=renderers[state.step]();renderTeacher();renderNavigation();$('back-step').disabled=state.step===0;$('next-step').textContent=state.step===7?'Finish lesson ✓':steps[state.step+1]?.lesson!==s.lesson?`Lesson ${steps[state.step+1].lesson} →`:'Next step →';updateTimer();restoreFeedback();bindAudio();if(state.step===7)renderFinish();}
function renderFinish(){if(!$('finish-message'))return;if(state.complete.has(7))$('finish-message').innerHTML=`<div class="success-card"><span class="card-label">YOUR NEXT STEP</span><h2>${state.complete.size===8?'The lesson is complete.':'Your final step is complete.'}</h2><p>${state.complete.size===8?'Share your response with your teacher, and keep a copy of your notes.':`${state.complete.size} of 8 steps are marked complete. You can return to any unfinished step.`}</p></div>`;else $('finish-message').innerHTML='';}
function announce(message){$('announcement').textContent=message;}
function navigate(i){if(!Number.isInteger(i)||i<0||i>=8)return;stopTimer();pauseAudio();state.step=i;markUnsaved();history.pushState(null,'',`#step-${i+1}`);render();$('lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});announce(`Step ${i+1}: ${steps[i].short}`);}
function setView(view){
  const teacher=view==='teacher';
  state.view=teacher?'teacher':'student';
  document.body.classList.toggle('student-mode',!teacher);
  $('teacher-panel').hidden=!teacher;
  const controls=$('view-switch');
  if(!teacher&&controls.contains(document.activeElement))$('teacher-tools-toggle').focus({preventScroll:true});
  controls.hidden=!teacher;
  $('student-view').setAttribute('aria-pressed',String(!teacher));
  $('teacher-view').setAttribute('aria-pressed',String(teacher));
  $('teacher-tools-toggle').setAttribute('aria-expanded',String(teacher));
  $('teacher-tools-toggle').setAttribute('aria-label',teacher?'Hide teacher guide':'Show teacher guide');
  announce(teacher?'Teacher view. Step-by-step teaching guidance is visible.':'Student view. Teacher guidance is hidden.');
}

function showFeedback(id,html,retry=false){const el=$(id);if(!el)return;el.innerHTML=html;el.classList.toggle('retry',retry);}
function checkReading(){const i=state.scene,s=scenes[i],v=state.drafts['read-'+i];if(v===undefined){showFeedback('reading-feedback','Choose an answer first.',true);return;}state.checked['reading-'+i]=true;const ok=Number(v)===s.answer;showFeedback('reading-feedback',`<strong>${ok?'That matches the story.':'Revisit the page and try again.'}</strong> ${s.explain}`,!ok);}
function checkSort(){const missing=phrases.filter((_,i)=>!state.drafts['sort-'+i]).length;if(missing){showFeedback('sort-feedback',`Choose a pattern for ${missing} more ${missing===1?'phrase':'phrases'}.`,true);return;}state.checked.sort=true;let correct=0;const results=phrases.map((p,i)=>{const ok=state.drafts['sort-'+i]===p.answer;if(ok)correct++;return `<p><strong>${ok?'✓':'Revisit:'} ${p.text}</strong> · ${p.why}</p>`;});showFeedback('sort-feedback',`<p><strong>${correct} of 6 correct.</strong> ${correct===6?'You are following what each word describes.':'Use the explanations, change your answers, and check again.'}</p>${results.join('')}`,correct<6);}
function checkForms(){const missing=formQuestions.filter((_,i)=>state.drafts['form-'+i]===undefined).length;if(missing){showFeedback('forms-feedback',`Choose an answer for all four sentences (${missing} still to do).`,true);return;}state.checked.forms=true;let correct=0;const results=formQuestions.map((q,i)=>{const ok=Number(state.drafts['form-'+i])===q.answer;if(ok)correct++;return `<p><strong>${i+1}. ${q.options[q.answer]}</strong> · ${q.why}</p>`;});showFeedback('forms-feedback',`<p><strong>${correct} of 4 correct.</strong> ${correct===4?'The form fits the job.':'Revisit the word being described.'}</p>${results.join('')}`,correct<4);}
function checkTransform(){const missing=transformations.filter((_,i)=>!normalizeAnswer(state.drafts['transform-'+i]||'')).length;if(missing){showFeedback('transform-feedback',`Complete ${missing} more ${missing===1?'rewrite':'rewrites'} before checking.`,true);return;}state.checked.transform=true;let correct=0;const results=transformations.map((t,i)=>{const ok=normalizeAnswer(state.drafts['transform-'+i])===t.answer;if(ok)correct++;return `<p><strong>${i+1}. ${t.before} ${t.answer} ${t.after}</strong><br>${t.why}</p>`;});showFeedback('transform-feedback',`<p><strong>${correct} of 3 correct.</strong></p>${results.join('')}`,correct<3);}
function checkChoiceSet(group,questions){const missing=questions.filter((_,i)=>state.drafts[group+'-'+i]===undefined).length;if(missing){showFeedback(group+'-feedback',`Answer ${missing} more ${missing===1?'question':'questions'} before checking.`,true);return;}state.checked[group]=true;let correct=0;const results=questions.map((q,i)=>{if(Number(state.drafts[group+'-'+i])===q.answer)correct++;return `<p><strong>${i+1}. ${q.options[q.answer]}</strong> · ${q.why}</p>`;});showFeedback(group+'-feedback',`<p><strong>${correct} of ${questions.length} correct.</strong></p>${results.join('')}`,correct<questions.length);}
function checkExistence(){checkChoiceSet('existence',existenceQuestions);}
function checkFuture(){checkChoiceSet('future',futureQuestions);}
function checkExit(){state.checked.exit=true;let checks=Array.from({length:6},(_,i)=>state.drafts['exit-check-'+i]).filter(Boolean).length;let combos=['exit-past','exit-future-noun','exit-future-verb'].filter(k=>String(state.drafts[k]||'').trim()).length;let count=wordCount(state.drafts['exit-response']||'');let text=`<strong>${checks} of 6 review points checked; ${combos} of 3 constructions identified.</strong> `;if(!count)text+='Write your response first.';else{text+=`Your response has ${count} words. `;if(count<80||count>100)text+='The suggested range is 80–100 words; review the length with your teacher if needed. ';text+='Read the three constructions in context with your teacher or partner. This checklist does not automatically grade grammar or the accuracy of predictions.';}showFeedback('exit-feedback',text,checks<6||combos<3||!count);}

function restoreFeedback(){if(state.step===1&&state.checked['reading-'+state.scene])checkReading();if(state.step===2&&state.checked.sort)checkSort();if(state.step===3){if(state.checked.forms)checkForms();if(state.checked.transform)checkTransform();if(state.checked.existence)checkExistence();}if(state.step===5&&state.checked.future)checkFuture();if(state.step===7&&state.checked.exit)checkExit();}
function clearActivityFeedback(el){const group=el.closest('[data-activity]')?.dataset.activity;if(group){if(group==='reading')delete state.checked['reading-'+state.scene];else delete state.checked[group];const id=group+'-feedback';if($(id))$(id).innerHTML='';}if(el.dataset.key?.startsWith('exit-')){delete state.checked.exit;if($('exit-feedback'))$('exit-feedback').innerHTML='';}}
function recordInput(el){const key=el.dataset.key;if(!key)return;if(el.type==='radio'&&!el.checked)return;const value=el.type==='checkbox'?el.checked:el.value;if(state.drafts[key]!==value)markUnsaved();state.drafts[key]=value;clearActivityFeedback(el);if(key==='exit-response')$('exit-count').textContent=`${wordCount(el.value)} words · suggested 80–100`;}

function updateTimer(){const time=timerHandle?Math.max(0,Math.ceil((timerDeadline-Date.now())/1000)):state.times[state.step];$('timer-time').textContent=formatTime(time);$('timer-toggle').textContent=timerHandle?'Pause':time===0?'Restart':'Start';$('timer-toggle').setAttribute('aria-label',timerHandle?'Pause timer':time===0?'Restart timer':'Start timer');$('timer').classList.toggle('timer-done',time===0);}
function stopTimer(){if(timerHandle){state.times[state.step]=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));clearInterval(timerHandle);timerHandle=null;}updateTimer();}
function toggleTimer(){if(timerHandle){stopTimer();return;}if(state.times[state.step]<=0)state.times[state.step]=steps[state.step].minutes*60;timerDeadline=Date.now()+state.times[state.step]*1000;timerHandle=setInterval(()=>{if(Date.now()>=timerDeadline){state.times[state.step]=0;clearInterval(timerHandle);timerHandle=null;announce('Suggested activity time has finished. Continue when ready.');}updateTimer();},250);updateTimer();}
function pauseAudio(){document.querySelectorAll('audio').forEach(a=>a.pause());}
function bindAudio(){document.querySelectorAll('audio').forEach(a=>{a.volume=.65;a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause();}));a.addEventListener('error',()=>{const note=document.createElement('p');note.className='hint';note.textContent='This sound could not load. Use the written description or try reloading the page.';if(!a.parentElement.querySelector('.audio-error')){note.classList.add('audio-error');a.after(note);}});});}

function printableValue(key,value){if(typeof value==='boolean')return value?'Reviewed':'Not reviewed';if(key.startsWith('existence-'))return existenceQuestions[Number(key.split('-')[1])]?.options[Number(value)]||value;if(key.startsWith('future-'))return futureQuestions[Number(key.split('-')[1])]?.options[Number(value)]||value;if(key.startsWith('sort-'))return value==='an'?'Adjective + noun':value==='va'?'Verb + adverb':value;if(key.startsWith('read-'))return scenes[Number(key.split('-')[1])]?.choices[Number(value)]||value;if(key.startsWith('form-'))return formQuestions[Number(key.split('-')[1])]?.options[Number(value)]||value;return value;}
function printNotes(){pauseAudio();const responses=steps.map((s,i)=>{const keys=Object.keys(state.drafts).filter(k=>state.fieldSteps[k]===i&&state.drafts[k]!==''&&state.drafts[k]!==false);const guide=state.view==='teacher'?`<section><h3>Teacher guide · ${s.minutes} minutes</h3><p><strong>Book:</strong> ${s.teacher.pages}</p><p>${s.teacher.goal}</p><ol>${s.teacher.actions.map(a=>`<li>${a}</li>`).join('')}</ol><p><strong>Look for:</strong> ${s.teacher.look}</p></section>`:'';return `<h2>Lesson ${s.lesson} · ${lessonTitles[s.lesson-1]} / Step ${i+1}: ${s.short}</h2>${guide}${keys.length?keys.map(k=>`<section><h3>${escape(state.labels[k]||k)}</h3><p>${escape(printableValue(k,state.drafts[k]))}</p></section>`).join(''):'<p>No written response recorded for this step.</p>'}`;}).join('');$('print-output').innerHTML=`<h1>The Silent Forest</h1><p class="print-meta">Music & Language · Four 40-minute lessons · ${state.view==='teacher'?'Teacher guide and lesson notes':'Student lesson notes'}</p>${responses}<p class="print-meta">Companion to Sinan Seden’s illustrated storybook. Unit 1, printed page 9, Exercise 6.</p>`;window.print();}

$('teacher-tools-toggle').addEventListener('click',()=>setView(state.view==='teacher'?'student':'teacher'));
$('student-view').addEventListener('click',()=>{setView('student');markUnsaved();});
$('teacher-view').addEventListener('click',()=>{setView('teacher');markUnsaved();});
$('step-nav').addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(b)navigate(Number(b.dataset.step));});
$('back-step').addEventListener('click',()=>navigate(state.step-1));
$('next-step').addEventListener('click',()=>{if(state.step<7)navigate(state.step+1);else{state.complete.add(7);markUnsaved();renderNavigation();renderFinish();$('finish-message').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});announce(state.complete.size===8?'All eight steps are complete.':'Final step marked complete. You can revisit any unfinished steps.');}});
$('complete-step').addEventListener('click',()=>{if(state.complete.has(state.step))state.complete.delete(state.step);else state.complete.add(state.step);markUnsaved();renderNavigation();renderFinish();announce(`${state.complete.size} of 8 steps marked complete.`);});
$('timer-toggle').addEventListener('click',toggleTimer);
$('timer-reset').addEventListener('click',()=>{stopTimer();state.times[state.step]=steps[state.step].minutes*60;updateTimer();});
$('print-work').addEventListener('click',printNotes);
$('step-content').addEventListener('input',e=>recordInput(e.target));
$('step-content').addEventListener('change',e=>recordInput(e.target));
$('step-content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.scene!==undefined){markUnsaved();state.scene=Number(b.dataset.scene);state.bookChapter=[1,4,13][state.scene];render();$('scene-tab-'+state.scene)?.focus({preventScroll:true});return;}if(b.dataset.book!==undefined){markUnsaved();state.bookChapter=Number(b.dataset.book);$('embedded-storybook').src='storybook.html?chapter='+state.bookChapter;$('book-large-link').href='storybook.html?chapter='+state.bookChapter;document.querySelectorAll('[data-book]').forEach(c=>c.setAttribute('aria-pressed',String(Number(c.dataset.book)===state.bookChapter)));return;}if(b.dataset.choice){const key=b.dataset.choice;remember(key,key==='selected-mood'?'Chosen soundtrack mood':key==='opening-position'?'Starting position':'Position after the story');state.drafts[key]=b.dataset.value;markUnsaved();document.querySelectorAll('[data-choice]').forEach(c=>{if(c.dataset.choice===key)c.setAttribute('aria-pressed',String(c.dataset.value===b.dataset.value));});if($('selected-mood-note'))$('selected-mood-note').textContent='Your choice: '+b.dataset.value;return;}if(b.dataset.check){const checks={reading:checkReading,sort:checkSort,forms:checkForms,transform:checkTransform,existence:checkExistence,future:checkFuture,exit:checkExit};checks[b.dataset.check]?.();markUnsaved();}if(b.dataset.action==='print')printNotes();});
$('step-content').addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();markUnsaved();state.scene=e.key==='Home'?0:e.key==='End'?2:(state.scene+(e.key==='ArrowRight'?1:2))%3;state.bookChapter=[1,4,13][state.scene];render();$('scene-tab-'+state.scene).focus();}});
window.addEventListener('popstate',()=>{stopTimer();pauseAudio();state.step=parseStep(location.hash);markUnsaved();render();$('lesson').focus({preventScroll:true});});
window.addEventListener('hashchange',()=>{const i=parseStep(location.hash);if(i!==state.step){stopTimer();pauseAudio();state.step=i;markUnsaved();render();$('lesson').focus({preventScroll:true});}});
window.addEventListener('pagehide',()=>{stopTimer();pauseAudio();});
document.querySelectorAll('[data-save-progress]').forEach(button=>button.addEventListener('click',saveAllProgress));
render();
setView(state.view);
if(savedProgress.status==='restored'){
  const message='Saved lesson restored · '+new Date(savedProgress.data.savedAt).toLocaleString()+'. Keep studying, then save your changes.';
  showSaveStatus(message,'saved');announce(message);
}else if(savedProgress.status==='unavailable'){
  showSaveStatus('Saved progress could not be read. You can keep working; try Save progress or use Print notes to keep a copy.','error');
}else{
  showSaveStatus('Save answers from all four lessons here before you leave.');
}
